const MN=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brl=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const brl0=v=>'R$ '+Math.round(v).toLocaleString('pt-BR');
const mi=v=>'R$ '+(v/1e6).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})+' mi';
const pct=(a,b)=>b?(a/b*100).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%':'—';
const sum=(a,k)=>a.reduce((s,r)=>s+r[k],0);
const fd=d=>d?d.split('-').reverse().join('/'):'';
const r2=v=>Math.round(v*100)/100;
const DRAFT_KEY='empenhos-rascunho-v1';

function codeCmp(a,b){const x=String(a).split('.').map(Number),y=String(b).split('.').map(Number);for(let i=0;i<Math.max(x.length,y.length);i++){const d=(x[i]||0)-(y[i]||0);if(d)return d}return 0}
const DATA_URL='empenhos.json';
const CFG=window.EMPENHOS_CONFIG||{};
const sb=(CFG.supabaseUrl&&CFG.supabaseAnonKey&&window.supabase)?window.supabase.createClient(CFG.supabaseUrl,CFG.supabaseAnonKey):null;
const ONLINE=!!sb;
async function loadBase(){
  if(sb){
    try{
      const {data,error}=await sb.from('painel').select('dados,atualizado').eq('id',1).maybeSingle();
      if(!error&&data&&data.dados)return {...data.dados,meta:{...(data.dados.meta||{}),atualizado:data.atualizado}};
    }catch(e){}
  }
  try{const r=await fetch(DATA_URL,{cache:'no-store'});if(!r.ok)throw new Error(r.status);return await r.json()}
  catch(e){if(window.EMPENHOS_DADOS)return window.EMPENHOS_DADOS;throw e}
}
let BASE;
try{BASE=await loadBase()}catch(e){
  $('#root').innerHTML='<div class="wrap"><section class="card"><h2>Não consegui carregar os dados</h2><p class="note" style="margin:0">O arquivo <code>data/empenhos.json</code> não foi encontrado ou está com erro. Se você abriu o <code>index.html</code> direto do computador, rode um servidor local (veja o README) ou publique a pasta no GitHub Pages ou Netlify.</p></section></div>';
  return;
}
BASE.meta=BASE.meta||{};BASE.rows=Array.isArray(BASE.rows)?BASE.rows:[];
if(!Array.isArray(BASE.oog)){const m={};BASE.rows.forEach(r=>{if(!r.item)return;(m[r.item]??={})[r.cat||r.esp]=(m[r.item][r.cat||r.esp]||0)+1});BASE={...BASE,oog:Object.keys(m).sort(codeCmp).map((c,i)=>({id:'o'+(i+1),cod:c,desc:Object.entries(m[c]).sort((x,y)=>y[1]-x[1])[0][0]}))}}
let S=BASE, admin=false, dirty=false, tab='painel', editing=null;
const ls={get(k){try{return localStorage.getItem(k)}catch(e){return null}},set(k,v){try{localStorage.setItem(k,v)}catch(e){}},del(k){try{localStorage.removeItem(k)}catch(e){}}};

