function calc(){const e=parseNum($('#f-emp').value),l=parseNum($('#f-liq').value);$('#f-calc').textContent=isFinite(e)&&isFinite(l)?brl(r2(e-l)):'—'}
function resetForm(){editing=null;$('#f').reset();$('#fh').textContent='Nova nota de empenho';$('#f-save').textContent='Salvar nota';$('#f-cancel').hidden=true;$('#f-err').hidden=true;calc()}
