  const ne=$('#f-ne').value.trim().replace(/\D/g,'').padStart(6,'0'),esp=$('#f-esp').value.trim(),nd=$('#f-nd').value.trim().replace(/\D/g,'');
  if(!data||!ne||!esp||!nd)return ferr('Preencha NE, data, especificação e ND.');
