  if(!isFinite(emp)||!isFinite(liq)||emp<0||liq<0)return ferr('Confira os valores. Use números como 1.234,56.');
  if(liq>emp+0.005)return ferr('O valor liquidado não pode ser maior que o empenho.');
  const rec={id:editing||nid(),ano:+data.slice(0,4),ne,data,nc:$('#f-nc').value.trim(),esp,cat:($('#f-cat').value.trim()||esp).toUpperCase(),item:$('#f-item').value,nd,emp:r2(emp),liq:r2(liq),aliq:r2(emp-liq)};
  if(!editing&&S.rows.some(r=>r.ne===ne&&r.ano===rec.ano))return ferr(`Já existe a NE ${ne}/${rec.ano}. Use Editar na lista abaixo.`);
  S={...S,rows:editing?S.rows.map(r=>r.id===editing?rec:r):[...S.rows,rec]};
